test('orphaned orders move to the placeholder, then the FK and CHECK constraints hold', async () => {
  const db = new PGlite()
  const dir = await mkdtemp(join(tmpdir(), 'migrations-'))
  // Stage 1: schema up to the orders index, as it was before the constraints.
  for (const file of ['0001_create_customers.sql', '0002_create_orders.sql', '0003_orders_notes.sql', '0004_deleted_customer_placeholder.sql', '0005_orders_customer_id_index.sql']) {
    await copyFile(join('migrations', file), join(dir, file))
  }
  await migrate(db, dir)
  await db.query(`INSERT INTO orders (customer_id, total_cents) VALUES (999999, 500)`)

  // Stage 2: the full migration set.
  await migrate(db)
  const orphan = await db.query(`SELECT c.email FROM orders o JOIN customers c ON c.id = o.customer_id`)
  assert.deepEqual(orphan.rows, [{ email: 'deleted-customer@internal.invalid' }])

  await db.query(`INSERT INTO customers (email, name) VALUES ('ana@example.com', 'Ana')`)
  const { rows } = await db.query(`SELECT id FROM customers WHERE email = 'ana@example.com'`)
  const anaId = Number((rows[0] as { id: number }).id)
  await db.query(`INSERT INTO orders (customer_id, total_cents) VALUES ($1, 100)`, [anaId])

  await assert.rejects(
    db.query(`INSERT INTO orders (customer_id, total_cents) VALUES (999999, 100)`),
    /orders_customer_id_fkey/,
  )
  await assert.rejects(db.query(`DELETE FROM customers WHERE id = $1`, [anaId]), /orders_customer_id_fkey/)
  await assert.rejects(
    db.query(`INSERT INTO orders (customer_id, total_cents) VALUES ($1, -1)`, [anaId]),
    /orders_total_cents_nonnegative/,
  )
})
